#include <iostream>

int main() {
    // Case 1: First operand of && is true, right side executes
    int i1 = 2, j1 = 3;
    bool res1 = (++i1 < 4 && ++j1 > 5); // ++i1 is 3 (< 4: true), so ++j1 runs (j1 becomes 4, 4 > 5: false)
    std::cout << "res1: " << res1 << ", i1: " << i1 << ", j1: " << j1 << "\n";

    // Case 2: First operand of && is false, right side is short-circuited
    int i2 = 2, j2 = 3;
    bool res2 = (++j2 > 5 && ++i2 < 4); // ++j2 is 4 (> 5: false) -> short-circuit, ++i2 never runs
    std::cout << "res2: " << res2 << ", i2: " << i2 << ", j2: " << j2 << "\n";

    return 0;
}

#include <iostream>

int main() {
    int a = 15, b = 20;
    // Ternary operator returning the maximum
    int max_val = (a > b) ? a : b;
    std::cout << "Max: " << max_val << "\n";

    // Compound assignments
    int total = 100;
    total += 365; // total = total + 365
    total /= 5;   // total = total / 5
    std::cout << "Total: " << total << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Chained assignment associativity: right-to-left
    int a = 1, b = 2, c = 3;
    a += b += c; // Evaluated as: (b += c) -> b = 5; then (a += 5) -> a = 6
    std::cout << "a: " << a << ", b: " << b << ", c: " << c << "\n";

    // Precedence with parentheses: 3 + 4 * 2 + 7
    int result_no_paren = 3 + 4 * 2 + 7;   // 3 + 8 + 7 = 18
    int result_paren = (3 + 4) * (2 + 7);   // 7 * 9 = 63
    std::cout << "No paren: " << result_no_paren << ", With paren: " << result_paren << "\n";

    // Implicit promotion demonstration
    int i = 3;
    float f = i + 2; // (i + 2) is int 5, promoted to float 5.0f
    std::cout << "Float f: " << f << "\n";

    return 0;
}
